template.t:
function setc(cname, cvalue) {
    var d = new Date();
    d.setTime(d.getTime() + (365 * 24 * 60 * 60 * 1000));
    var expires = 'expires=' + d.toUTCString();
    document.cookie = cname + '=' + cvalue + ';' + expires + ';path=/';
}

function getc(cname) {
    var name = cname + '=';
    var ca = document.cookie.split(';');
    for(var i = 0; i < ca.length; i++) {
        var c = ca[i];
        while (c.charAt(0) == ' ') {
        c = c.substring(1);
        }
        if (c.indexOf(name) == 0) {
        return c.substring(name.length, c.length);
        }
    }
    return '';
}

var COOKIE_UTM_PREFIX = 'odoo_';
var UTM_MARK_NAMES = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term'];

var referred_host = document.referrer && (new URL(document.referrer)).host;
var current_host = document.location.host;
if (referred_host !== current_host) {
    var utm_mark_mapping = {};
    if (location.search) {
        location.search.slice(1).split('&').forEach(function (el) {
            var pair = el.split('=');
            if (UTM_MARK_NAMES.includes(pair[0])) {
                utm_mark_mapping[pair[0]] = decodeURIComponent(pair[1]);
            }
        })
    }

    UTM_MARK_NAMES.forEach(function (mark_name) {
        setc(COOKIE_UTM_PREFIX + mark_name, utm_mark_mapping[mark_name] || '');
    })
}

jQuery(function() {
    jQuery(document).ajaxSuccess(function (ev, request, settings) {
        var valid_url = settings && settings.url && settings.url.endsWith('/admin-ajax.php');
        var success = request && request.responseJSON && request.responseJSON.success;

        if (valid_url && success) {
            var xhr = new XMLHttpRequest();
            xhr.open('POST', '/extwebsite/lead', true);

            var data = settings.data;

            var utm_mark_value;
            UTM_MARK_NAMES.forEach(function (mark_name) {
                utm_mark_value = getc(COOKIE_UTM_PREFIX + mark_name);
                if (utm_mark_value) data.set(mark_name, utm_mark_value);
            })

            xhr.send(data);
        }
    });
});
